INSERT INTO `competencias_ciclos` (`id`, `codigo`, `texto`, `tipo`, `idCiclo`, `orden`) VALUES
(1, 'a', 'Preparar equipos y aplicaciones informáticas para llevar a cabo la grabación, tratamiento, impresión, reproducción y archivado de datos y textos, asegurando su funcionamiento.', 1, 6, 1),
(2, 'b', 'Elaborar documentos mediante las utilidades básicas de las aplicaciones informáticas de los procesadores de texto y hojas de cálculo aplicando procedimientos de escritura al tacto con exactitud y rapidez, archivando la información y documentación, tanto en soporte digital como convencional, de acuer', 1, 6, 2),
(3, 'c', 'Acopiar los materiales para acometer el montaje y/o mantenimiento en sistemas microinformáticos y redes de transmisión de datos.', 1, 6, 3),
(4, 'd', 'Realizar operaciones auxiliares de montaje de sistemas microinformáticos y dispositivos auxiliares en condiciones de calidad.', 1, 6, 4),
(5, 'e', 'Realizar operaciones auxiliares de mantenimiento y reparación de sistemas microinformáticos garantizando su funcionamiento.', 1, 6, 5),
(6, 'f', 'Realizar las operaciones para el almacenamiento y transporte de sistemas, periféricos y consumibles, siguiendo criterios de seguridad y catalogación.', 1, 6, 6),
(7, 'g', 'Realizar comprobaciones rutinarias de verificación en el montaje y mantenimiento de sistemas y/o instalaciones.', 1, 6, 7),
(8, 'h', 'Montar canalizaciones para cableado de datos en condiciones de calidad y seguridad.', 1, 6, 8),
(9, 'i', 'Tender el cableado de redes de datos aplicando las técnicas y procedimientos normalizados.', 1, 6, 9),
(10, 'j', 'Manejar las herramientas del entorno usuario proporcionadas por el sistema operativo y los dispositivos de almacenamiento de información.', 1, 6, 10),
(11, 'k', 'Resolver problemas predecibles relacionados con su entorno físico, social, personal y productivo, utilizando el razonamiento científico y los elementos proporcionados por las ciencias aplicadas y sociales.', 2, 6, 11),
(12, 'l', 'Actuar de forma saludable en distintos contextos cotidianos que favorezcan el desarrollo personal y social, analizando hábitos e influencias positivas para la salud humana.', 2, 6, 12),
(13, 'm', 'Valorar actuaciones encaminadas a la conservación del medio ambiente diferenciando las consecuencias de las actividades cotidianas que pueda afectar al equilibrio del mismo.', 2, 6, 13),
(14, 'n', 'Obtener y comunicar información destinada al autoaprendizaje y a su uso en distintos contextos de su entorno personal, social o profesional mediante recursos a su alcance y los propios de las tecnologías de la información y de la comunicación.', 2, 6, 14),
(15, 'ñ', 'Actuar con respeto y sensibilidad hacia la diversidad cultural, el patrimonio histórico-artístico y las manifestaciones culturales y artísticas, apreciando su uso y disfrute como fuente de enriquecimiento personal y social.', 2, 6, 15),
(16, 'o', 'Comunicarse con claridad, precisión y fluidez en distintos contextos sociales o profesionales y por distintos medios, canales y soportes a su alcance, utilizando y adecuando recursos lingüísticos orales y escritos propios de la lengua castellana y, en su caso, de la lengua cooficial.', 2, 6, 16),
(17, 'p', 'Comunicarse en situaciones habituales tanto laborales como personales y sociales utilizando recursos lingüísticos básicos en lengua extranjera.', 2, 6, 17),
(18, 'q', 'Realizar explicaciones sencillas sobre acontecimientos y fenómenos característicos de las sociedades contemporáneas a partir de información histórica y geográfica a su disposición.', 2, 6, 18),
(19, 'r', 'Adaptarse a las nuevas situaciones laborales originadas por cambios tecnológicos y organizativos en su actividad laboral, utilizando las ofertas formativas a su alcance y localizando los recursos mediante las tecnologías de la información y la comunicación.', 2, 6, 19),
(20, 's', 'Cumplir las tareas propias de su nivel con autonomía y responsabilidad, empleando criterios de calidad y eficiencia en el trabajo asignado y efectuándolo de forma individual o como miembro de un equipo.', 2, 6, 20),
(21, 't', 'Comunicarse eficazmente, respetando la autonomía y competencia de las distintas personas que intervienen en su ámbito de trabajo, contribuyendo a la calidad del trabajo realizado.', 2, 6, 21),
(22, 'u', 'Asumir y cumplir las medidas de prevención de riesgos y seguridad laboral en la realización de las actividades laborales evitando daños personales, laborales y ambientales.', 2, 6, 22),
(23, 'v', 'Cumplir las normas de calidad, de accesibilidad universal y diseño para todos que afectan a su actividad profesional.', 2, 6, 23),
(24, 'w', 'Actuar con espíritu emprendedor, iniciativa personal y responsabilidad en la elección de los procedimientos de su actividad profesional.', 2, 6, 24),
(25, 'x', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de su actividad profesional, de acuerdo con lo establecido en la legislación vigente, participando activamente en la vida económica, social y cultural.', 2, 6, 25),
(26, 'a', 'Acopiar los materiales para acometer el montaje y/o mantenimiento en sistemas microinformáticos y redes de transmisión de datos.', 1, 7, 1),
(27, 'b', 'Realizar operaciones auxiliares de montaje de sistemas microinformáticos y dispositivos auxiliares en condiciones de calidad.', 1, 7, 2),
(28, 'c', 'Realizar operaciones auxiliares de mantenimiento y reparación de sistemas microinformáticos garantizando su funcionamiento.', 1, 7, 3),
(29, 'd', 'Realizar las operaciones para el almacenamiento y transporte de sistemas, periféricos y consumibles, siguiendo criterios de seguridad y catalogación.', 1, 7, 4),
(30, 'e', 'Realizar comprobaciones rutinarias de verificación en el montaje y mantenimiento de sistemas y/o instalaciones.', 1, 7, 5),
(31, 'f', 'Montar canalizaciones para cableado de datos en condiciones de calidad y seguridad.', 1, 7, 6),
(32, 'g', 'Tender el cableado de redes de datos aplicando las técnicas y procedimientos normalizados.', 1, 7, 7),
(33, 'h', 'Manejar las herramientas del entorno usuario proporcionadas por el sistema operativo y los dispositivos de almacenamiento de información.', 1, 7, 8),
(34, 'i', 'Manejar aplicaciones ofimáticas de procesador de textos para realizar documentos sencillos.', 1, 7, 9),
(35, 'j', 'Resolver problemas predecibles relacionados con su entorno físico, social, personal y productivo, utilizando el razonamiento científico y los elementos proporcionados por las ciencias aplicadas y sociales.', 2, 7, 10),
(36, 'k', 'Actuar de forma saludable en distintos contextos cotidianos que favorezcan el desarrollo personal y social, analizando hábitos e influencias positivas para la salud humana.', 2, 7, 11),
(37, 'l', 'Valorar actuaciones encaminadas a la conservación del medio ambiente diferenciando las consecuencias de las actividades cotidianas que pueda afectar al equilibrio del mismo.', 2, 7, 12),
(38, 'm', 'Obtener y comunicar información destinada al autoaprendizaje y a su uso en distintos contextos de su entorno personal, social o profesional mediante recursos a su alcance y los propios de las tecnologías de la información y de la comunicación.', 2, 7, 13),
(39, 'n', 'Actuar con respeto y sensibilidad hacia la diversidad cultural, el patrimonio histórico-artístico y las manifestaciones culturales y artísticas, apreciando su uso y disfrute como fuente de enriquecimiento personal y social.', 2, 7, 14),
(40, 'ñ', 'Comunicarse con claridad, precisión y fluidez en distintos contextos sociales o profesionales y por distintos medios, canales y soportes a su alcance, utilizando y adecuando recursos lingüísticos orales y escritos propios de la lengua castellana y, en su caso, de la lengua cooficial.', 2, 7, 15),
(41, 'o', 'Comunicarse en situaciones habituales tanto laborales como personales y sociales utilizando recursos lingüísticos básicos en lengua extranjera.', 2, 7, 16),
(42, 'p', 'Realizar explicaciones sencillas sobre acontecimientos y fenómenos característicos de las sociedades contemporáneas a partir de información histórica y geográfica a su disposición.', 2, 7, 17),
(43, 'q', 'Adaptarse a las nuevas situaciones laborales originadas por cambios tecnológicos y organizativos en su actividad laboral, utilizando las ofertas formativas a su alcance y localizando los recursos mediante las tecnologías de la información y la comunicación.', 2, 7, 18),
(44, 'r', 'Cumplir las tareas propias de su nivel con autonomía y responsabilidad, empleando criterios de calidad y eficiencia en el trabajo asignado y efectuándolo de forma individual o como miembro de un equipo.', 2, 7, 19),
(45, 's', 'Comunicarse eficazmente, respetando la autonomía y competencia de las distintas personas que intervienen en su ámbito de trabajo, contribuyendo a la calidad del trabajo realizado.', 2, 7, 20),
(46, 't', 'Asumir y cumplir las medidas de prevención de riesgos y seguridad laboral en la realización de las actividades laborales evitando daños personales, laborales y ambientales.', 2, 7, 21),
(47, 'u', 'Cumplir las normas de calidad, de accesibilidad universal y diseño para todos que afectan a su actividad profesional.', 2, 7, 22),
(48, 'v', 'Actuar con espíritu emprendedor, iniciativa personal y responsabilidad en la elección de los procedimientos de su actividad profesional.', 2, 7, 23),
(49, 'w', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de su actividad profesional, de acuerdo con lo establecido en la legislación vigente, participando activamente en la vida económica, social y cultural.', 2, 7, 24),
(50, 'a', 'Configurar y explotar sistemas informáticos, adaptando la configuración lógica del sistema según las necesidades de uso y los criterios establecidos.', 1, 2, 1),
(51, 'b', 'Aplicar técnicas y procedimientos relacionados con la seguridad en sistemas, servicios y aplicaciones, cumpliendo el plan de seguridad.', 1, 2, 2),
(52, 'c', 'Gestionar bases de datos, interpretando su diseño lógico y verificando integridad, consistencia, seguridad y accesibilidad de los datos.', 1, 2, 3),
(53, 'd', 'Gestionar entornos de desarrollo adaptando su configuración en cada caso para permitir el desarrollo y despliegue de aplicaciones.', 1, 2, 4),
(54, 'e', 'Desarrollar aplicaciones multiplataforma con acceso a bases de datos utilizando lenguajes, librerías y herramientas adecuados a las especificaciones.', 1, 2, 5),
(55, 'f', 'Desarrollar aplicaciones implementando un sistema completo de formularios e informes que permitan gestionar de forma integral la información almacenada.', 1, 2, 6),
(56, 'g', 'Integrar contenidos gráficos y componentes multimedia en aplicaciones multiplataforma, empleando herramientas específicas y cumpliendo los requerimientos establecidos.', 1, 2, 7),
(57, 'h', 'Desarrollar interfaces gráficos de usuario interactivos y con la usabilidad adecuada, empleando componentes visuales estándar o implementando componentes visuales específicos.', 1, 2, 8),
(58, 'i', 'Participar en el desarrollo de juegos y aplicaciones en el ámbito del entretenimiento y la educación empleando técnicas, motores y entornos de desarrollo específicos.', 1, 2, 9),
(59, 'j', 'Desarrollar aplicaciones para teléfonos móviles, tabletas y otros dispositivos inteligentes empleando técnicas y entornos de desarrollo específicos.', 1, 2, 10),
(60, 'k', 'Crear ayudas generales y sensibles al contexto, empleando herramientas específicas e integrándolas en sus correspondientes aplicaciones.', 1, 2, 11),
(61, 'l', 'Crear tutoriales, manuales de usuario, de instalación, de configuración y de administración, empleando herramientas específicas.', 1, 2, 12),
(62, 'm', 'Empaquetar aplicaciones para su distribución preparando paquetes auto instalables con asistentes incorporados.', 1, 2, 13),
(63, 'n', 'Desarrollar aplicaciones multiproceso y multihilo empleando librerías y técnicas de programación específicas.', 1, 2, 14),
(64, 'ñ', 'Desarrollar aplicaciones capaces de ofrecer servicios en red empleando mecanismos de comunicación.', 1, 2, 15),
(65, 'o', 'Participar en la implantación de sistemas ERP-CRM evaluando la utilidad de cada uno de sus módulos.', 1, 2, 16),
(66, 'p', 'Gestionar la información almacenada en sistemas ERP-CRM garantizando su integridad.', 1, 2, 17),
(67, 'q', 'Desarrollar componentes personalizados para un sistema ERP-CRM atendiendo a los requerimientos.', 1, 2, 18),
(68, 'r', 'Realizar planes de pruebas verificando el funcionamiento de los componentes software desarrollados, según las especificaciones.', 1, 2, 19),
(69, 's', 'Desplegar y distribuir aplicaciones en distintos ámbitos de implantación verificando su comportamiento y realizando las modificaciones necesarias.', 1, 2, 20),
(70, 't', 'Establecer vidas eficaces de relación profesional y comunicación con sus superiores, compañeros y subordinados, respetando la autonomía y competencias de las distintas personas.', 2, 2, 21),
(71, 'u', 'Liderar situaciones colectivas que se puedan producir, mediando en conflictos personales y laborales, contribuyendo al establecimiento de un ambiente de trabajo agradable, actuando en todo momento de forma respetuosa y tolerante.', 2, 2, 22),
(72, 'v', 'Gestionar su carrera profesional, analizando las oportunidades de empleo, autoempleo y de aprendizaje.', 2, 2, 23),
(73, 'w', 'Mantener el espíritu de innovación y actualización en el ámbito de su trabajo para adaptarse a los cambios tecnológicos y organizativos de su entorno profesional.', 2, 2, 24),
(74, 'x', 'Crear y gestionar una pequeña empresa, realizando un estudio de viabilidad de productos, de planificación de la producción y de comercialización.', 2, 2, 25),
(75, 'y', 'Participar de forma activa en la vida económica, social y cultural, con una actitud crítica y responsable.', 2, 2, 26),
(76, 'a', 'Determinar la logística asociada a las operaciones de instalación, configuración y mantenimiento de sistemas microinformáticos, interpretando la documentación técnica asociada y organizando los recursos necesarios.', 1, 5, 1),
(77, 'b', 'Montar y configurar ordenadores y periféricos, asegurando su funcionamiento en condiciones de calidad y seguridad.', 1, 5, 2),
(78, 'c', 'Instalar y configurar software básico y de aplicación, asegurando su funcionamiento en condiciones de calidad y seguridad.', 1, 5, 3),
(79, 'd', 'Replantear el cableado y la electrónica de redes locales en pequeños entornos y su conexión con redes de área extensa canalizando a un nivel superior los supuestos que así lo requieran.', 1, 5, 4),
(80, 'e', 'Instalar y configurar redes locales cableadas, inalámbricas o mixtas y su conexión a redes públicas, asegurando su funcionamiento en condiciones de calidad y seguridad.', 1, 5, 5),
(81, 'f', 'Instalar, configurar y mantener servicios multiusuario, aplicaciones y dispositivos compartidos en un entorno de red local, atendiendo a las necesidades y requerimientos especificados.', 1, 5, 6),
(82, 'g', 'Realizar las pruebas funcionales en sistemas microinformáticos y redes locales, localizando y diagnosticando disfunciones, para comprobar y ajustar su funcionamiento.', 1, 5, 7),
(83, 'h', 'Mantener sistemas microinformáticos y redes locales, sustituyendo, actualizando y ajustando sus componentes, para asegurar el rendimiento del sistema en condiciones de calidad y seguridad.', 1, 5, 8),
(84, 'i', 'Ejecutar procedimientos establecidos de recuperación de datos y aplicaciones ante fallos y pérdidas de datos en el sistema, para garantizar la integridad y disponibilidad de la información.', 1, 5, 9),
(85, 'j', 'Elaborar documentación técnica y administrativa del sistema, cumpliendo las normas y reglamentación del sector, para su mantenimiento y la asistencia al cliente.', 1, 5, 10),
(86, 'k', 'Elaborar presupuestos de sistemas a medida cumpliendo los requerimientos del cliente.', 1, 5, 11),
(87, 'l', 'Asesorar y asistir al cliente, canalizando a un nivel superior los supuestos que lo requieran, para encontrar soluciones adecuadas a las necesidades de éste.', 1, 5, 12),
(88, 'm', 'Organizar y desarrollar el trabajo asignado manteniendo unas relaciones profesionales adecuadas en el entorno de trabajo.', 2, 5, 13),
(89, 'n', 'Mantener un espíritu constante de innovación y actualización en el ámbito del sector informático.', 2, 5, 14),
(90, 'ñ', 'Utilizar los medios de consulta disponibles, seleccionando el más adecuado en cada caso, para resolver en tiempo razonable supuestos no conocidos y dudas profesionales.', 2, 5, 15),
(91, 'o', 'Aplicar los protocolos y normas de seguridad, calidad y respeto al medio ambiente en las intervenciones realizadas.', 2, 5, 16),
(92, 'p', 'Cumplir con los objetivos de la producción, colaborando con el equipo de trabajo y actuando conforme a los principios de responsabilidad y tolerancia.', 2, 5, 17),
(93, 'q', 'Adaptarse a diferentes puestos de trabajo y nuevas situaciones laborales originados por cambios tecnológicos y organizativos en los procesos productivos.', 2, 5, 18),
(94, 'r', 'Resolver problemas y tomar decisiones individuales siguiendo las normas y procedimientos establecidos definidos dentro del ámbito de su competencia.', 2, 5, 19),
(95, 's', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de las relaciones laborales, de acuerdo con lo establecido en la legislación vigente.', 2, 5, 20),
(96, 't', 'Gestionar su carrera profesional, analizando las oportunidades de empleo, autoempleo y aprendizaje.', 2, 5, 21),
(97, 'u', 'Crear y gestionar una pequeña empresa, realizando un estudio de viabilidad de productos, planificación de la producción y comercialización.', 2, 5, 22),
(98, 'v', 'Participar de forma activa en la vida económica, social y cultural, con una actitud crítica y responsable.', 2, 5, 23),
(99, '1', 'Administrar sistemas operativos de servidor, instalando y configurando el software, en condiciones de calidad para asegurar el funcionamiento del sistema.', 1, 4, 1),
(100, '2', 'Administrar servicios de red (web, mensajería electrónica y transferencia de archivos, entre otros) instalando y configurando el software, en condiciones de calidad.', 1, 4, 2),
(101, '3', 'Administrar aplicaciones instalando y configurando el software, en condiciones de calidad para responder a las necesidades de la organización.', 1, 4, 3),
(102, '4', 'Implantar y gestionar bases de datos instalando y administrando el software de gestión en condiciones de calidad, según las características de la explotación.', 1, 4, 4),
(103, '5', 'Optimizar el rendimiento del sistema configurando los dispositivos hardware de acuerdo a los requisitos de funcionamiento.', 1, 4, 5),
(104, '6', 'Evaluar el rendimiento de los dispositivos hardware identificando posibilidades de mejoras según las necesidades de funcionamiento.', 1, 4, 6),
(105, '7', 'Determinar la infraestructura de redes telemáticas elaborando esquemas y seleccionando equipos y elementos.', 1, 4, 7),
(106, '8', 'Integrar equipos de comunicaciones en infraestructuras de redes telemáticas, determinando la configuración para asegurar su conectividad.', 1, 4, 8),
(107, '9', 'Implementar soluciones de alta disponibilidad, analizando las distintas opciones del mercado, para proteger y recuperar el sistema ante situaciones imprevistas.', 1, 4, 9),
(108, '10', 'Supervisar la seguridad física según especificaciones del fabricante y el plan de seguridad para evitar interrupciones en la prestación de servicios del sistema.', 1, 4, 10),
(109, '11', 'Asegurar el sistema y los datos según las necesidades de uso y las condiciones de seguridad establecidas para prevenir fallos y ataques externos.', 1, 4, 11),
(110, '12', 'Administrar usuarios de acuerdo a las especificaciones de explotación para garantizar los accesos y la disponibilidad de los recursos del sistema.', 1, 4, 12),
(111, '13', 'Diagnosticar las disfunciones del sistema y adoptar las medidas correctivas para restablecer su funcionalidad.', 1, 4, 13),
(112, '14', 'Gestionar y/o realizar el mantenimiento de los recursos de su área (programando y verificando su cumplimiento), en función de las cargas de trabajo y el plan de mantenimiento.', 1, 4, 14),
(113, '15', 'Efectuar consultas, dirigiéndose a la persona adecuada y saber respetar la autonomía de los subordinados, informando cuando sea conveniente.', 1, 4, 15),
(114, '16', 'Mantener el espíritu de innovación y actualización en el ámbito de su trabajo para adaptarse a los cambios tecnológicos y organizativos de su entorno profesional.', 2, 4, 16),
(115, '17', 'Liderar situaciones colectivas que se puedan producir, mediando en conflictos personales y laborales, contribuyendo al establecimiento de un ambiente de trabajo agradable y actuando en todo momento de forma sincera, respetuosa y tolerante.', 2, 4, 17),
(116, '18', 'Resolver problemas y tomar decisiones individuales, siguiendo las normas y procedimientos establecidos, definidos dentro del ámbito de su competencia.', 2, 4, 18),
(117, '19', 'Gestionar su carrera profesional, analizando las oportunidades de empleo, autoempleo y de aprendizaje.', 2, 4, 19),
(118, '20', 'Participar de forma activa en la vida económica, social y cultural con actitud crítica y responsable.', 2, 4, 20),
(119, '21', 'Crear y gestionar una pequeña empresa, realizando un estudio de viabilidad de productos, de planificación de la producción y de comercialización.', 2, 4, 21),
(120, 'a', 'Configurar y explotar sistemas informáticos, adaptando la configuración lógica del sistema según las necesidades de uso y los criterios establecidos.', 1, 3, 1),
(121, 'b', 'Aplicar técnicas y procedimientos relacionados con la seguridad en sistemas, servicios y aplicaciones, cumpliendo el plan de seguridad.', 1, 3, 2),
(122, 'c', 'Gestionar servidores en distintos ámbitos de implantación adaptando su configuración en cada caso para permitir el despliegue de aplicaciones web.', 1, 3, 3),
(123, 'd', 'Gestionar bases de datos, interpretando su diseño lógico y verificando integridad, consistencia, seguridad y accesibilidad de los datos.', 1, 3, 4),
(124, 'e', 'Desarrollar aplicaciones web con acceso a bases de datos utilizando lenguajes, objetos de acceso y herramientas de mapeo adecuados a las especificaciones.', 1, 3, 5),
(125, 'f', 'Integrar contenidos en la lógica de una aplicación web, desarrollando componentes de acceso a datos adecuados a las especificaciones.', 1, 3, 6),
(126, 'g', 'Desarrollar interfaces en aplicaciones web de acuerdo con un manual de estilo, utilizando lenguajes de marcas y estándares web.', 1, 3, 7),
(127, 'h', 'Desarrollar componentes multimedia para su integración en aplicaciones web, empleando herramientas específicas y siguiendo las especificaciones establecidas.', 1, 3, 8),
(128, 'i', 'Integrar componentes multimedia en la interface de una aplicación web, realizando el análisis de interactividad, accesibilidad y usabilidad de la aplicación.', 1, 3, 9),
(129, 'j', 'Desarrollar e integrar componentes software en el entorno del servidor web, empleando herramientas y lenguajes específicos, para cumplir las especificaciones de la aplicación.', 1, 3, 10),
