(180, 'Herminia Pastor', 'HPAS', 'hpastor', 'cbc3ac0ed34b3a51e53ebcc61366e8ee', 'INF', '', 1, 'Docencia en la universidad los lunes de 11:00 a 15:00', 'h.pastorpina@edu.gva.es', 1, 0, 1, '609290841'),
(181, 'María Corpus Barón', 'MCOR', 'mcbaron', 'd769807825669c70fee279afb532f5b9', 'INF', '', 26, '', NULL, 1, 0, 1, '647942392'),
